(6542564, 973607, 66384, '<td valign="top">Well done. This is hard to guess. I think a pipe was cloned out.</td>', 'Well done. This is hard to guess. I think a pipe was cloned out.', '2011-09-16 22:11:00.000000', NULL, 1),
(6542570, 973422, 66384, '<td valign="top">I''m thinking this is real. I''m guessing you took a photo and are displaying it on the screen, perhaps as the wallpaper image. Very cool effect well done.</td>', 'I''m thinking this is real. I''m guessing you took a photo and are displaying it on the screen, perhaps as the wallpaper image. Very cool effect well done.', '2011-09-16 22:21:58.000000', NULL, 1),
(6542576, 973600, 66384, '<td valign="top">Beautiful scene without the surfer, which looks rather like a blemish. I''m guessing this is real; done with a long exposure and perhaps a zoom..</td>', 'Beautiful scene without the surfer, which looks rather like a blemish. I''m guessing this is real; done with a long exposure and perhaps a zoom..', '2011-09-16 22:29:26.000000', NULL, 1),
