(6542581, 973546, 66384, '<td valign="top">Real?</td>', 'Real?', '2011-09-16 22:33:21.000000', NULL, 1),
(6542583, 973010, 66384, '<td valign="top">Real?</td>', 'Real?', '2011-09-16 22:34:11.000000', NULL, 1),
